def auth(v):
    u,p=os.getenv("DASHBOARD_USER","").strip(),os.getenv("DASHBOARD_PASSWORD","").strip()
    if not u or not p or not v or not v.startswith("Basic "): return False
    try:
        a,b=base64.b64decode(v[6:]).decode().split(":",1)
        return secrets.compare_digest(a,u) and secrets.compare_digest(b,p)
    except Exception: return False

def req(v):
    if not auth(v): raise HTTPException(401,"Dashboard authentication required",headers={"WWW-Authenticate":"Basic"})

def esc(v): return html.escape(str(v if v is not None else ""),quote=True)

def label(ind): return next((x[0] for x in BUSINESS_TYPES if x[1]==ind),str(ind).title())

class Status(BaseModel): status:str
class DiscoveryRequest(BaseModel): business_type:str; city:str; limit:int=20

async def run_discovery(city:str, industry:str, limit:int):
    db=Database(); job=await db.create_job("DISCOVERY",city,industry); saved=failed=0
    try:
        candidates=await discover_businesses(city,industry,min(max(limit,1),50))
        google=await google_places_enrich(city,industry,candidates)
        for i,c in enumerate(candidates):
            try:
                if i<10: r=await research_business(c)
                else: r={"website":{"exists":bool(c.get("website"))},"seo":{"score":100 if c.get("website") else 0},"local":{"phone_found":bool(c.get("phone")),"email_found":bool(c.get("email"))},"google":{},"search":{},"profiles":{},"problems":[]}
                r["search"]=dict(r.get("search") or {}); r["search"]["query"]=google.get("query")
                r["google"]={**(r.get("google") or {}),"local_rank":c.get("google_local_rank"),"rating":c.get("google_rating"),"review_count":c.get("google_review_count"),"maps_url":c.get("google_maps_url")}
                sc=score_lead(r); r["score_breakdown"]=sc.get("breakdown",[])
                bid,_=await db.upsert_business(c)
                if bid: await db.save_research_and_score(bid,r,sc); saved+=1
                else: failed+=1
            except Exception:
                failed+=1; log.exception("dashboard lead processing failed")
        if job: await db.finish_job(job,len(candidates),saved,failed)
    except Exception as exc:
        if job: await db.finish_job(job,0,0,1,str(exc)[:1000])
        log.exception("dashboard discovery failed")

@router.get("/dashboard",response_class=HTMLResponse)
async def dashboard(authorization:str|None=Header(default=None)):
    req(authorization); db=Database(); stats=await db.today_stats(); history=await db.history(14)
    return HTMLResponse(PAGE.replace("__STATS__",json.dumps(stats)).replace("__HISTORY__",json.dumps(history)).replace("__STAGES__",json.dumps(STAGES)).replace("__BUSINESS_TYPES__",json.dumps(BUSINESS_TYPES,ensure_ascii=False)).replace("__CITIES__",json.dumps(CITIES,ensure_ascii=False)))

@router.get("/dashboard/api/leads")
async def leads(authorization:str|None=Header(default=None),priority:str|None=None,limit:int=Query(500,ge=1,le=1000),offset:int=Query(0,ge=0)):
    req(authorization); db=Database(); rows=await db.list_leads(priority,limit,offset); out=[]
    for x in rows:
        try:r=await db.get_research(int(x["id"]))
        except Exception:r={}
        try:a=await db.activities(int(x["id"]),20)
        except Exception:a=[]
        out.append({**x,"research":r or {},"activities":a or []})
    return {"ok":True,"leads":out,"count":len(out)}

@router.post("/dashboard/api/discover")
async def discover(payload:DiscoveryRequest,background_tasks:BackgroundTasks,authorization:str|None=Header(default=None)):
    req(authorization)
    if payload.business_type not in {x[1] for x in BUSINESS_TYPES}: raise HTTPException(400,"Unsupported business type")
    if payload.city not in CITIES: raise HTTPException(400,"Unsupported Madhya Pradesh city")
    limit=min(max(int(payload.limit),1),50)
    db=Database(); job=await db.create_job("DISCOVERY",payload.city,payload.business_type)
    # Mark this job as the UI job; the worker updates a separate job when running so the dashboard can show a clean queued state.
    background_tasks.add_task(_run_job,job,payload.city,payload.business_type,limit)
    return {"ok":True,"job_id":job,"status":"RUNNING","city":payload.city,"business_type":payload.business_type,"limit":limit}

async def _run_job(job_id,city,industry,limit):
    db=Database(); saved=failed=0
    try:
        candidates=await discover_businesses(city,industry,limit); google=await google_places_enrich(city,industry,candidates)
        for i,c in enumerate(candidates):
            try:
                r=await research_business(c) if i<10 else {"website":{"exists":bool(c.get("website"))},"seo":{"score":100 if c.get("website") else 0},"local":{"phone_found":bool(c.get("phone")),"email_found":bool(c.get("email"))},"google":{},"search":{},"profiles":{},"problems":[]}
                r["search"]=dict(r.get("search") or {}); r["search"]["query"]=google.get("query")
                r["google"]={**(r.get("google") or {}),"local_rank":c.get("google_local_rank"),"rating":c.get("google_rating"),"review_count":c.get("google_review_count"),"maps_url":c.get("google_maps_url")}
                sc=score_lead(r); r["score_breakdown"]=sc.get("breakdown",[]); bid,_=await db.upsert_business(c)
                if bid: await db.save_research_and_score(bid,r,sc); saved+=1
                else: failed+=1
            except Exception: failed+=1; log.exception("dashboard discovery item failed")
        await db.finish_job(job_id,len(candidates),saved,failed)
    except Exception as exc: await db.finish_job(job_id,0,0,1,str(exc)[:1000])

@router.get("/dashboard/api/jobs/{job_id}")
async def job_status(job_id:int,authorization:str|None=Header(default=None)):
    req(authorization); db=Database();
    r=db.client.table("jobs").select("*").eq("id",job_id).limit(1).execute()
    return {"ok":True,"job":r.data[0] if r.data else None}

@router.post("/dashboard/api/leads/{business_id}/message")
async def pitch_message(business_id:int,authorization:str|None=Header(default=None)):
    req(authorization); db=Database(); lead=await db.get_lead(business_id)
    if not lead: raise HTTPException(404,"Lead not found")
    text=await generate_whatsapp_message(lead,await db.get_research(business_id)); await db.record_activity(business_id,"MESSAGE_GENERATED","dashboard","Pitch message generated"); return {"ok":True,"message":text}

@router.patch("/dashboard/api/leads/{business_id}/status")
async def status(business_id:int,payload:Status,authorization:str|None=Header(default=None)):
    req(authorization)
    if payload.status not in {x[0] for x in STAGES}: raise HTTPException(400,"Invalid status")
    db=Database(); await db.set_status(business_id,payload.status); await db.record_activity(business_id,"STATUS_"+payload.status,"dashboard","Status changed from dashboard"); return {"ok":True,"status":payload.status}

